    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    const p_ada_2 = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    await ui.loadSheet(pg_uma, `${sheet}-c`);
    await ui.setSetting(pg_uma, "parent", `${sheet}`);
    await ui.loadSheet(pg_uma, sheet);
    const pl_ada_1 = ui.must(await ui.addPlan(pg_uma, p_ada_2, {"amount": "10.00", "start": "2026-03-01", "end": "2026-03-20", "sheet": `${sheet}-c`, "every": "5"}));
    const pl_ben_2 = ui.must(await ui.addPlan(pg_uma, p_ben, {"amount": "5.00", "start": "2026-03-01", "end": "2026-03-20", "sheet": `${sheet}-c`, "every": "5"}));
    expect(await ui.addPlan(pg_uma, p_ada_2, {"amount": "1.00", "start": "2026-03-01", "end": "2026-03-20", "sheet": `${sheet}-x`, "every": "5"})).toBeNull();
    expect(await ui.generatePlans(pg_uma)).toBe(1);
    await ui.setToday(pg_uma, "2026-03-12");
    expect(await ui.generatePlans(pg_uma)).toBe(2);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("person-row-" + p_ada_2).getByTestId("person-claimed")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
