      `PLAN_ADDED sheet=${sheet} by=uma name=Ben amount=5.00 start=2026-03-01 every=5 end=2026-03-20 sheet=${sheet}-c`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ada due-total=0.00`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ben due-total=n/a`
    ]);
